### 3. **script.js** (לוגיקה)
```javascript
const STORAGE_KEY = 'todo.toDoList';

const todoListEl = document.getElementById('todo-list');
const formEl = document.getElementById('todo-form');
const inputEl = document.getElementById('todo-input');

function loadTodos() {
 const stored = localStorage.getItem(STORAGE_KEY);
 return stored ? JSON.parse(stored) : [];
}

function saveTodos(todos) {
 localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

function createTodoElement(todo) {
 const li = document.createElement('li');
 li.className = todo.completed ? 'completed' : '';
 li.dataset.id = todo.id;

 const checkbox = document.createElement('input');
 checkbox.type = 'checkbox';
 checkbox.checked = todo.completed;
 checkbox.addEventListener('change', () => toggleCompleted(todo.id));

 const label = document.createElement('label');
 label.textContent = todo.text;

 const deleteBtn = document.createElement('button');
 deleteBtn.innerHTML = '&times;';
 deleteBtn.addEventListener('click', () => deleteTodo(todo.id));

 li.append(checkbox, label, deleteBtn);
 return li;
}

function toggleCompleted(id) {
 const todos = loadTodos();
 const index = todos.findIndex(t => t.id === id);
 if (index !== -1) {
 todos[index].completed = !todos[index].completed;
 saveTodos(todos);
 renderTodos();
 }
}

function deleteTodo(id) {
 let todos = loadTodos();
 todos = todos.filter(t => t.id !== id);
 saveTodos(todos);
 renderTodos();
}

function addTodo(text) {
 const todos = loadTodos();
 todos.push({ id: Date.now().toString(), text, completed: false });
 saveTodos(todos);
 renderTodos();
 inputEl.value = '';
}

function renderTodos() {
 const todos = loadTodos();
 todoListEl.innerHTML = '';
 todos.forEach(todo => todoListEl.appendChild(createTodoElement(todo)));
}

formEl.addEventListener('submit', (e) => {
 e.preventDefault();
 if (inputEl.value.trim()) {
 addTodo(inputEl.value.trim());
 }
});

renderTodos();
```

